const listLatestOccurrencesForSchedules = `-- name: ListLatestOccurrencesForSchedules :many
SELECT o.id, o.schedule_id, o.scheduled_at, o.enqueued_at, o.admitted_at, o.run_id,
       o.status, o.triggered_at, o.finished_at, o.created_at, o.updated_at
FROM schedule_occurrences o
JOIN (
    SELECT x.schedule_id, MAX(x.id) AS max_id
    FROM schedule_occurrences x
    WHERE x.schedule_id IN (/*SLICE:ids*/?)
    GROUP BY x.schedule_id
) m ON o.schedule_id = m.schedule_id AND o.id = m.max_id
`

func (q *Queries) ListLatestOccurrencesForSchedules(ctx context.Context, ids []uint64) ([]ScheduleOccurrence, error) {
	query := listLatestOccurrencesForSchedules
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScheduleOccurrence{}
	for rows.Next() {
		var i ScheduleOccurrence
		if err := rows.Scan(
			&i.ID,
			&i.ScheduleID,
			&i.ScheduledAt,
			&i.EnqueuedAt,
			&i.AdmittedAt,
			&i.RunID,
			&i.Status,
			&i.TriggeredAt,
			&i.FinishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

